create or replace function public.handle_new_auth_user() returns trigger language plpgsql security definer set search_path='pg_catalog','public' as $$begin if new.id is null or new.email is null or exists(select from public.usuario where lower(correo)=lower(new.email) and supabase_uid<>new.id) then raise exception 'profile identity conflict'; end if; insert into public.usuario(id,supabase_uid,correo,nombre,rol,fecha_registro,empresa_id,onboarding,updated_at) values(new.id,new.id,new.email,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1)),'cliente',now(),null,true,now()) on conflict(supabase_uid) do nothing; if not exists(select from public.usuario where id=new.id and supabase_uid=new.id and rol='cliente' and empresa_id is null and onboarding) then raise exception 'profile identity conflict'; end if; return new; end$$;
